请对以下 case 进行三维加权评分。

=== case_id ===
Case-22-express-013

=== 用户原始指令 (query.txt) ===
快递明天到,整张卡片用顺丰那种黑色背景,顶部显示天气和明天日期,下面几个件都显示已签收完成,用📦字符图标,下面能滚动看更多件。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "快递明天到,整张卡片用顺丰那种黑色背景,顶部显示天气和明天日期,下面几个件都显示已签收完成,用📦字符图标,下面能滚动看更多件。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    },
    "ui": {
      "tomorrowText": {
        "type": "string",
        "description": "明天日期的短展示文本。",
        "sampleValue": "明天 07/10"
      }
    },
    "delivery": {
      "summaryTitle": {
        "type": "string",
        "description": "快递到达与签收状态摘要标题。",
        "sampleValue": "明日到达"
      },
      "summaryCaption": {
        "type": "string",
        "description": "快递列表整体状态说明。",
        "sampleValue": "全部已签收"
      },
      "packages": {
        "type": "array",
        "description": "可滚动展示的快递条目列表。",
        "sampleValue": [
          {
            "title": "生鲜件",
            "status": "已签收"
          },
          {
            "title": "文件件",
            "status": "已签收"
          },
          {
            "title": "日用品",
            "status": "已签收"
          },
          {
            "title": "配件包",
            "status": "已签收"
          },
          {
            "title": "补发件",
            "status": "已签收"
          }
        ],
        "items": {
          "type": "object",
          "description": "单个快递条目。",
          "properties": {
            "title": {
              "type": "string",
              "description": "快递件的短名称。",
              "sampleValue": "生鲜件"
            },
            "status": {
              "type": "string",
              "description": "快递件的签收状态。",
              "sampleValue": "已签收"
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "快递箱子彩色图标，适合用于物流信息、包裹识别和取件提醒。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "云朵组合彩色天气图标，适合用于多云天气和出行天气提示。"
    }
  ]
}

